// 📁 src/pages/admin/AdminOffres.jsx
import { useEffect, useState } from "react";
import {
  fetchOffres,
  ajouterOffre,
  modifierOffre,
  supprimerOffre,
} from "@/utils/adminApi";
import { toast } from "react-toastify";
import { Pencil, Trash2, Plus, Check, X } from "lucide-react";

/** 👉 Normalise n'importe quelle forme en tableau */
const asArray = (raw) => {
  if (Array.isArray(raw)) return raw;
  if (Array.isArray(raw?.data)) return raw.data;
  if (Array.isArray(raw?.rows)) return raw.rows;
  if (Array.isArray(raw?.items)) return raw.items;
  if (Array.isArray(raw?.offres)) return raw.offres;
  if (raw && typeof raw === "object") return Object.values(raw);
  return [];
};

export default function AdminOffres() {
  const [offres, setOffres] = useState([]); // toujours un tableau
  const [search, setSearch] = useState("");
  const [editId, setEditId] = useState(null);

  // pour créer/éditer
  const [nouvelleOffre, setNouvelleOffre] = useState({
    titre: "",
    description: "",
    type_contrat: "",
    lieu: "",
    categorie: "",
  });
  const [offreEdite, setOffreEdite] = useState({
    titre: "",
    description: "",
    type_contrat: "",
    lieu: "",
    categorie: "",
  });

  useEffect(() => {
    chargerOffres();
  }, []);

  const chargerOffres = async () => {
    try {
      const data = await fetchOffres();                 // peut être {offres:[...]}, etc.
      setOffres(asArray(data?.offres ?? data));         // normalisé
    } catch (err) {
      console.error("Erreur chargement offres:", err);
      toast.error("Erreur chargement des offres");
      setOffres([]);
    }
  };

  /* -------- Création -------- */
  const handleAjouter = async (ev) => {
    ev.preventDefault();
    try {
      await ajouterOffre(nouvelleOffre);
      toast.success("Offre ajoutée !");
      setNouvelleOffre({
        titre: "",
        description: "",
        type_contrat: "",
        lieu: "",
        categorie: "",
      });
      chargerOffres();
    } catch (err) {
      console.error("Erreur ajout:", err);
      toast.error("Erreur lors de l'ajout");
    }
  };

  /* -------- Édition -------- */
  const handleEdit = (o) => {
    const id = o.id ?? o._id ?? o.uuid ?? null;
    setEditId(id);
    setOffreEdite({
      titre: o.titre ?? "",
      description: o.description ?? "",
      type_contrat: o.type_contrat ?? "",
      lieu: o.lieu ?? "",
      categorie: o.categorie ?? "",
    });
  };

  const handleUpdate = async (id) => {
    try {
      await modifierOffre(id, offreEdite);
      toast.success("Offre modifiée !");
      setEditId(null);
      chargerOffres();
    } catch (err) {
      console.error("Erreur modification:", err);
      toast.error("Erreur lors de la modification");
    }
  };

  /* -------- Suppression -------- */
  const handleSupprimer = async (id) => {
    if (!window.confirm("Confirmer la suppression ?")) return;
    try {
      await supprimerOffre(id);
      toast.success("Offre supprimée !");
      chargerOffres();
    } catch (err) {
      console.error("Erreur suppression:", err);
      toast.error("Erreur lors de la suppression");
    }
  };

  /* -------- Filtre recherche -------- */
  const q = search.trim().toLowerCase();
  const offresFiltrees = asArray(offres).filter((o) =>
    (o?.titre ?? "").toLowerCase().includes(q)
  );

  return (
    <div className="max-w-5xl mx-auto px-4 py-8">
      <h1 className="text-2xl font-bold text-red-600 mb-4">Gestion des Offres</h1>

      {/* 🔍 Recherche */}
      <input
        type="text"
        placeholder="Rechercher une offre..."
        value={search}
        onChange={(ev) => setSearch(ev.target.value)}
        className="w-full border px-4 py-2 rounded mb-4"
      />

      {/* ➕ Ajout */}
      <form onSubmit={handleAjouter} className="bg-white p-4 rounded shadow mb-6 space-y-3">
        <h2 className="text-lg font-semibold">Ajouter une offre</h2>
        <input
          type="text"
          placeholder="Titre"
          value={nouvelleOffre.titre}
          onChange={(e) => setNouvelleOffre({ ...nouvelleOffre, titre: e.target.value })}
          className="w-full border px-3 py-2 rounded"
          required
        />
        <textarea
          placeholder="Description"
          value={nouvelleOffre.description}
          onChange={(e) => setNouvelleOffre({ ...nouvelleOffre, description: e.target.value })}
          className="w-full border px-3 py-2 rounded"
          rows={3}
          required
        />

        {/* Champs optionnels (type, lieu, catégorie) */}
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
          <input
            type="text"
            placeholder="Type de contrat"
            value={nouvelleOffre.type_contrat}
            onChange={(e) =>
              setNouvelleOffre({ ...nouvelleOffre, type_contrat: e.target.value })
            }
            className="w-full border px-3 py-2 rounded"
          />
          <input
            type="text"
            placeholder="Lieu"
            value={nouvelleOffre.lieu}
            onChange={(e) => setNouvelleOffre({ ...nouvelleOffre, lieu: e.target.value })}
            className="w-full border px-3 py-2 rounded"
          />
          <input
            type="text"
            placeholder="Catégorie"
            value={nouvelleOffre.categorie}
            onChange={(e) => setNouvelleOffre({ ...nouvelleOffre, categorie: e.target.value })}
            className="w-full border px-3 py-2 rounded"
          />
        </div>

        <button type="submit" className="bg-red-600 text-white px-4 py-2 rounded hover:bg-red-700">
          <Plus className="inline mr-1" size={18} />
          Ajouter
        </button>
      </form>

      {/* 📋 Liste */}
      <div className="space-y-4">
        {asArray(offresFiltrees).map((o) => {
          const id = o.id ?? o._id ?? o.uuid ?? String(o.titre || Math.random());
          const isEditing = editId === id;

          return (
            <div
              key={id}
              className="bg-white p-4 shadow rounded flex justify-between items-start gap-4"
            >
              {/* Colonne contenu */}
              {isEditing ? (
                <div className="flex-1 space-y-2">
                  <input
                    type="text"
                    value={offreEdite.titre}
                    onChange={(e) => setOffreEdite({ ...offreEdite, titre: e.target.value })}
                    className="w-full border rounded px-3 py-2"
                  />
                  <textarea
                    value={offreEdite.description}
                    onChange={(e) =>
                      setOffreEdite({ ...offreEdite, description: e.target.value })
                    }
                    className="w-full border rounded px-3 py-2"
                    rows={3}
                  />
                  <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
                    <input
                      type="text"
                      placeholder="Type de contrat"
                      value={offreEdite.type_contrat}
                      onChange={(e) =>
                        setOffreEdite({ ...offreEdite, type_contrat: e.target.value })
                      }
                      className="w-full border px-3 py-2 rounded"
                    />
                    <input
                      type="text"
                      placeholder="Lieu"
                      value={offreEdite.lieu}
                      onChange={(e) =>
                        setOffreEdite({ ...offreEdite, lieu: e.target.value })
                      }
                      className="w-full border px-3 py-2 rounded"
                    />
                    <input
                      type="text"
                      placeholder="Catégorie"
                      value={offreEdite.categorie}
                      onChange={(e) =>
                        setOffreEdite({ ...offreEdite, categorie: e.target.value })
                      }
                      className="w-full border px-3 py-2 rounded"
                    />
                  </div>
                </div>
              ) : (
                <div className="flex-1">
                  <h3 className="text-lg font-semibold">{o.titre}</h3>
                  <p className="text-gray-700">{o.description}</p>
                  <div className="text-xs text-gray-500 mt-2 flex flex-wrap gap-3">
                    {o.type_contrat && <span>Contrat : {o.type_contrat}</span>}
                    {o.lieu && <span>Lieu : {o.lieu}</span>}
                    {o.categorie && <span>Catégorie : {o.categorie}</span>}
                  </div>
                </div>
              )}

              {/* Colonne actions */}
              <div className="flex-shrink-0 space-x-2">
                {isEditing ? (
                  <>
                    <button
                      onClick={() => handleUpdate(id)}
                      className="text-green-600 hover:underline"
                      title="Enregistrer"
                    >
                      <Check size={20} />
                    </button>
                    <button
                      onClick={() => setEditId(null)}
                      className="text-gray-500 hover:underline"
                      title="Annuler"
                    >
                      <X size={20} />
                    </button>
                  </>
                ) : (
                  <>
                    <button
                      onClick={() => handleEdit({ ...o, id })}
                      className="text-blue-600 hover:underline"
                      title="Modifier"
                    >
                      <Pencil size={20} />
                    </button>
                    <button
                      onClick={() => handleSupprimer(id)}
                      className="text-red-600 hover:underline"
                      title="Supprimer"
                    >
                      <Trash2 size={20} />
                    </button>
                  </>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
